package studio.jiayu.neoagent;

public final class VoiceCaptureRulesTest {
 static int checks;
 static void yes(boolean value,String label){if(!value)throw new AssertionError(label);checks++;}
 static final class Capture {
  final VoiceSession session=new VoiceSession();final Object record=new Object();final long lease;final VoiceCaptureRules rules;
  Capture(){lease=session.begin(true);session.listening(lease);rules=new VoiceCaptureRules(lease,record);rules.start(lease,record,0);}
  void prefix(){session.segment(lease,"先打开企业微信然后");}
  boolean apply(VoiceCaptureRules.Signal signal){return VoiceCaptureRules.forceDraft(session,rules,lease,record,signal);}
  VoiceSession.Result finish(){session.stop(lease);return session.finish(lease,true);}
 }
 static void draft(VoiceCaptureRules.Signal signal,String label){Capture c=new Capture();c.prefix();yes(c.apply(signal),label+" accepted");VoiceSession.Result result=c.finish();yes(result!=null&&!result.direct&&result.text.equals("先打开企业微信然后"),label+" preserves only committed draft");}
 public static void main(String[] args){
  Capture c=new Capture();c.prefix();yes(c.rules.configuration(c.lease,c.record,true,false,11,10)==VoiceCaptureRules.Signal.NONE,"first valid route accepted");yes(c.rules.configuration(c.lease,c.record,true,false,11,20)==VoiceCaptureRules.Signal.NONE,"same route remains healthy");yes(c.finish().direct,"normal user stop retains direct mode");
  draft(VoiceCaptureRules.Signal.SYSTEM_SILENCED,"system silence");draft(VoiceCaptureRules.Signal.ROUTE_CHANGED,"route switch");draft(VoiceCaptureRules.Signal.CONFIGURATION_LOST,"active capture lost");draft(VoiceCaptureRules.Signal.MONITOR_UNAVAILABLE,"monitor unavailable");draft(VoiceCaptureRules.Signal.READ_ERROR,"read failure");draft(VoiceCaptureRules.Signal.INPUT_STALLED,"no PCM progress");
  c=new Capture();yes(c.rules.configuration(c.lease,c.record,false,false,0,1499)==VoiceCaptureRules.Signal.NONE,"initial configuration may arrive asynchronously");yes(c.rules.configuration(c.lease,c.record,false,false,0,1500)==VoiceCaptureRules.Signal.CONFIGURATION_LOST,"unknown startup cannot silently remain direct");
  c=new Capture();c.prefix();yes(c.rules.completion(c.lease,c.record)==VoiceCaptureRules.Signal.MONITOR_UNAVAILABLE,"early user stop still requires known active capture");c.apply(c.rules.completion(c.lease,c.record));yes(!c.finish().direct,"startup grace cannot permit an unmonitored direct final");
  c=new Capture();c.rules.configuration(c.lease,c.record,true,false,11,1);yes(c.rules.configuration(c.lease,c.record,false,false,0,2)==VoiceCaptureRules.Signal.CONFIGURATION_LOST,"previously active capture disappearing has no grace");yes(c.rules.configuration(c.lease,c.record,true,true,11,3)==VoiceCaptureRules.Signal.SYSTEM_SILENCED,"silenced config has precedence");yes(c.rules.configuration(c.lease,c.record,true,false,12,4)==VoiceCaptureRules.Signal.ROUTE_CHANGED,"new nonzero route invalidates utterance");
  c=new Capture();yes(c.rules.read(c.lease,c.record,0,1499)==VoiceCaptureRules.Signal.NONE,"temporary empty read is tolerated");yes(c.rules.read(c.lease,c.record,80,1499)==VoiceCaptureRules.Signal.NONE,"data resets empty-read deadline");yes(c.rules.read(c.lease,c.record,0,2998)==VoiceCaptureRules.Signal.NONE,"fresh data extends progress window");yes(c.rules.read(c.lease,c.record,0,2999)==VoiceCaptureRules.Signal.INPUT_STALLED,"zero reads cannot bypass deadlines forever");yes(c.rules.read(c.lease,c.record,-6,3000)==VoiceCaptureRules.Signal.READ_ERROR,"native read errors are interruptions");
  c=new Capture();c.prefix();yes(!VoiceCaptureRules.forceDraft(c.session,c.rules,c.lease,new Object(),VoiceCaptureRules.Signal.SYSTEM_SILENCED),"foreign recorder callback rejected");yes(!VoiceCaptureRules.forceDraft(c.session,c.rules,c.lease+1,c.record,VoiceCaptureRules.Signal.SYSTEM_SILENCED),"foreign lease callback rejected");yes(c.finish().direct,"foreign callbacks cannot downgrade current speech");
  c=new Capture();c.prefix();c.rules.configuration(c.lease,c.record,true,false,11,10);yes(c.rules.completion(c.lease,c.record)==VoiceCaptureRules.Signal.NONE,"healthy early user stop has no interruption");c.rules.end(c.lease,c.record);yes(!c.apply(VoiceCaptureRules.Signal.CONFIGURATION_LOST),"normal stop disarms subsequent inactive-config callback");yes(c.finish().direct,"intentional stop is not an interruption");
  c=new Capture();c.prefix();yes(c.apply(VoiceCaptureRules.Signal.SYSTEM_SILENCED),"first interruption latches");yes(!c.apply(VoiceCaptureRules.Signal.ROUTE_CHANGED),"duplicate callback has no second effect");yes(c.rules.configuration(c.lease,c.record,true,false,11,2000)==VoiceCaptureRules.Signal.NONE,"unsilencing cannot rearm interrupted capture");yes(c.rules.interruption()==VoiceCaptureRules.Signal.SYSTEM_SILENCED&&!c.finish().direct,"recovery never restores direct execution to truncated utterance");
  c=new Capture();c.session.preview(c.lease,"未确认的部分识别");c.apply(VoiceCaptureRules.Signal.READ_ERROR);yes(c.finish()==null,"interruption never promotes partial ASR to a final");
  c=new Capture();c.prefix();long old=c.lease;Object oldRecord=c.record;VoiceCaptureRules oldRules=c.rules;c.session.cancel();long next=c.session.begin(true);c.session.listening(next);c.session.segment(next,"打开高德地图");yes(!VoiceCaptureRules.forceDraft(c.session,oldRules,old,oldRecord,VoiceCaptureRules.Signal.SYSTEM_SILENCED),"old callback cannot alter next session");yes(c.session.finish(next,true).direct,"new session direct mode survives stale callback");
  VoiceSession s=new VoiceSession();long lease=s.begin(true);s.listening(lease);Object record=new Object();VoiceCaptureRules notStarted=new VoiceCaptureRules(lease,record);yes(!VoiceCaptureRules.forceDraft(s,notStarted,lease,record,VoiceCaptureRules.Signal.SYSTEM_SILENCED),"pre-start callback ignored");yes(notStarted.start(lease,record,50),"valid recorder can start after initial callback");yes(!notStarted.start(lease,record,60),"duplicate starts rejected");s.segment(lease,"打开微信");notStarted.end(lease,record);yes(!notStarted.start(lease,record,70),"ended recorder cannot restart");yes(s.finish(lease,true).direct,"pre-start callback cannot contaminate later healthy capture");
  c=new Capture();c.prefix();c.apply(VoiceCaptureRules.Signal.SYSTEM_SILENCED);yes(c.session.finish(c.lease,false)==null,"interrupted background capture cannot deliver a draft");
  System.out.println("PASS: VoiceCaptureRules "+checks+" continuity, interruption, identity and draft-only checks");
 }
}
